259: function Get-UsageFromEvents {
260:     param([string]$Path)
261:     $text = Read-SharedText -Path $Path
262:     if (-not $text) { return $null }
263:     $usage = $null
264:     foreach ($line in ($text -split "`r?`n")) {
265:         if ($line.IndexOf('turn.completed') -lt 0) { continue }
266:         $trimmed = $line.Trim()
267:         if (-not $trimmed.StartsWith('{')) { continue }
