272:         if ($obj.PSObject.Properties['usage']) { $u = $obj.usage }
273:         $values = [ordered]@{}
274:         foreach ($field in @('input_tokens', 'cached_input_tokens', 'output_tokens', 'reasoning_output_tokens')) {
